package com.utetra.order.service;
import com.utetra.order.entity.*;
import com.utetra.order.dto.OrderRequests.Actor;
import com.utetra.order.repository.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import org.springframework.beans.factory.annotation.Value;
import java.util.*;
import java.time.*;
import java.math.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
/** Local wallet simulation inspired by the reference cinema project; never a bank receipt. */
@Service @Transactional(isolation=Isolation.READ_COMMITTED)
public class LocalQrPaymentService {
 private final OrderDataRepository data;private final CommerceReferenceRepository refs;private final OrderSupport support;private final Clock clock;private final byte[] secret;private final boolean enabled;private final String baseUrl;
 public LocalQrPaymentService(OrderDataRepository data,CommerceReferenceRepository refs,OrderSupport support,Clock clock,@Value("${payment.local-qr.enabled:true}") boolean enabled,@Value("${payment.local-qr.secret:}") String configured,@Value("${payment.local-qr.base-url:http://127.0.0.1:8080}") String baseUrl){this.data=data;this.refs=refs;this.support=support;this.clock=clock;this.enabled=enabled;this.baseUrl=baseUrl.replaceAll("/+$","");if(!this.baseUrl.matches("https?://[^/?#@]+"))throw new IllegalArgumentException("Địa chỉ ví không hợp lệ.");this.secret=loadKey(configured);}
 private byte[] loadKey(String configured){if(!configured.isBlank()){if(configured.length()<32)throw new IllegalArgumentException("Khóa ví cần ít nhất 32 ký tự.");return configured.getBytes(StandardCharsets.UTF_8);}try{Path path=Path.of(".local","local-qr.key");Files.createDirectories(path.getParent());if(!Files.exists(path)){byte[] key=new byte[32];new SecureRandom().nextBytes(key);try{Files.write(path,key,StandardOpenOption.CREATE_NEW);}catch(FileAlreadyExistsException raced){}}byte[] key=Files.readAllBytes(path);if(key.length!=32)throw new IllegalStateException("Khóa ví local không hợp lệ.");return key;}catch(java.io.IOException error){throw new IllegalStateException("Không đọc được khóa ví local.",error);}}
 public boolean available(){return enabled;}
 private void requireEnabled(){if(!enabled)throw OrderProblem.conflict("Thanh toán QR chưa sẵn sàng.");}
 private String token(LocalQrPayment payment){try{Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(secret,"HmacSHA256"));return Base64.getUrlEncoder().withoutPadding().encodeToString(mac.doFinal(payment.publicId.getBytes(StandardCharsets.US_ASCII)));}catch(GeneralSecurityException error){throw new IllegalStateException(error);}}
 private String hash(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.US_ASCII)));}catch(GeneralSecurityException error){throw new IllegalStateException(error);}}
 private void verify(LocalQrPayment payment,String token){if(token==null||!token.matches("[A-Za-z0-9_-]{43}")||!MessageDigest.isEqual(hash(token).getBytes(StandardCharsets.US_ASCII),payment.tokenHash.getBytes(StandardCharsets.US_ASCII)))throw OrderProblem.forbidden();}
 private List<LocalQrPayment> rows(long order){return data.query(LocalQrPayment.class,"where e.orderId=:order order by e.id",Map.of("order",order),false,100);}
 public void create(Order order){requireEnabled();if(!"LOCAL_QR".equals(order.paymentMethod))return;data.flush();Map<Long,BigDecimal> amounts=new LinkedHashMap<>();
  if(order.groupOrderId!=null&&"INDIVIDUAL".equals(refs.one("select payment_mode from group_orders where id=?",order.groupOrderId).get("payment_mode"))){for(var row:refs.list("select user_id,amount_due from group_order_members where order_id=? order by id",order.id))amounts.put(((Number)row.get("user_id")).longValue(),new BigDecimal(row.get("amount_due").toString()));}else amounts.put(order.userId,order.finalAmount);
  if(amounts.isEmpty()||amounts.values().stream().anyMatch(amount->amount.signum()<0)||amounts.values().stream().reduce(BigDecimal.ZERO,BigDecimal::add).compareTo(order.finalAmount)!=0)throw OrderProblem.conflict("Phần thanh toán không khớp tổng đơn.");
  for(var amount:amounts.entrySet()){var payment=new LocalQrPayment();payment.orderId=order.id;payment.userId=amount.getKey();payment.publicId=UUID.randomUUID().toString();payment.amount=amount.getValue();payment.status=payment.amount.signum()==0?"SUCCESS":"PENDING";payment.createdAt=clock.instant();payment.expiresAt=clock.instant().plus(Duration.ofMinutes(30));if("SUCCESS".equals(payment.status))payment.paidAt=clock.instant();payment.tokenHash=hash(token(payment));data.save(payment);}data.flush();
 }
 private LocalQrPayment own(Actor actor,long order){support.buyer(actor);refs.requireCurrent(actor,false);return rows(order).stream().filter(payment->payment.userId==actor.userId()).findFirst().orElseThrow(OrderProblem::forbidden);}
 private LocalQrPayment find(String id){try{UUID.fromString(id);}catch(Exception error){throw OrderProblem.missing();}return data.query(LocalQrPayment.class,"where e.publicId=:id",Map.of("id",id),false,1).stream().findFirst().orElseThrow(OrderProblem::missing);}
 private String state(LocalQrPayment payment,Order order){if(Set.of("CANCELLED","REFUNDED","REFUND_PENDING").contains(order.status)||Set.of("CANCELLED","REFUNDED","REFUND_PENDING").contains(order.paymentStatus))return "CANCELLED";if("SUCCESS".equals(payment.status))return "SUCCESS";return payment.expiresAt.isAfter(clock.instant())?"PENDING":"EXPIRED";}
 private Map<String,Object> view(LocalQrPayment payment,Order order){var all=rows(order.id);Map<String,Object> result=new LinkedHashMap<>();result.put("id",payment.publicId);result.put("orderId",order.id);result.put("orderCode",order.orderCode);result.put("amount",payment.amount);result.put("state",state(payment,order));result.put("orderPaymentStatus",order.paymentStatus);result.put("paidCount",all.stream().filter(row->"SUCCESS".equals(row.status)).count());result.put("payerCount",all.size());result.put("expiresAt",payment.expiresAt.toString());result.put("serverNow",clock.instant().toString());return result;}
 @Transactional(readOnly=true) public Map<String,Object> merchant(Actor actor,long id){requireEnabled();var payment=own(actor,id);var order=data.require(Order.class,id,false);var result=view(payment,order);result.put("walletUrl",baseUrl+"/local-wallet/pay/"+payment.publicId+"#token="+token(payment));return result;}
 @Transactional(readOnly=true) public Map<String,Object> publicStatus(String id,String token){requireEnabled();var payment=find(id);verify(payment,token);return view(payment,data.require(Order.class,payment.orderId,false));}
 public Map<String,Object> confirm(String id,String token,BigDecimal expected,boolean acknowledged){requireEnabled();try{UUID.fromString(id);}catch(Exception error){throw OrderProblem.missing();}var locator=refs.one("select id,order_id from local_qr_payments where public_id=?",id);var order=data.require(Order.class,((Number)locator.get("order_id")).longValue(),true);var payment=data.require(LocalQrPayment.class,((Number)locator.get("id")).longValue(),true);verify(payment,token);refs.user(payment.userId,false);if(!acknowledged||expected==null||expected.compareTo(payment.amount)!=0)throw OrderProblem.invalid("Vui lòng kiểm tra số tiền và xác nhận thanh toán nội bộ.");String state=state(payment,order);if("SUCCESS".equals(state))return view(payment,order);if(!"PENDING".equals(state))throw OrderProblem.conflict("Giao dịch đã hết hạn hoặc đơn đã hủy.");if(!"LOCAL_QR".equals(order.paymentMethod)||!"NEW".equals(order.status)||!"UNPAID".equals(order.paymentStatus))throw OrderProblem.conflict("Đơn không nhận thanh toán này.");payment.status="SUCCESS";payment.paidAt=clock.instant();data.flush();assertLedger(data,refs,order,false);var all=rows(order.id);if(all.stream().allMatch(row->"SUCCESS".equals(row.status))){order.paymentStatus="PAID";order.paidAt=clock.instant();order.updatedAt=clock.instant();var aggregate=data.query(PaymentTransaction.class,"where e.orderId=:order and e.provider='LOCAL_QR'",Map.of("order",order.id),true,1).getFirst();aggregate.status="SUCCEEDED";aggregate.providerTxnId="LOCAL-"+order.id;aggregate.paidAt=clock.instant();aggregate.updatedAt=clock.instant();support.event(order,null,order.status,"LOCAL_QR_ALL_PAID","Toàn bộ phần tiền đã thanh toán qua hệ thống nội bộ.");}return view(payment,order);}
 public Map<String,Object> renew(Actor actor,long id){requireEnabled();support.buyer(actor);refs.requireCurrent(actor,false);var locator=refs.one("select id from local_qr_payments where order_id=? and user_id=?",id,actor.userId());var order=data.require(Order.class,id,true);var payment=data.require(LocalQrPayment.class,((Number)locator.get("id")).longValue(),true);if(!"EXPIRED".equals(state(payment,order)))throw OrderProblem.conflict("Chỉ tạo lại QR đã hết hạn.");payment.publicId=UUID.randomUUID().toString();payment.tokenHash=hash(token(payment));payment.expiresAt=clock.instant().plus(Duration.ofMinutes(30));data.flush();return merchant(actor,id);}
 public static void assertLedger(OrderDataRepository data,CommerceReferenceRepository refs,Order order,boolean requirePaid){if(!"LOCAL_QR".equals(order.paymentMethod))return;var all=data.query(LocalQrPayment.class,"where e.orderId=:order",Map.of("order",order.id),false,100);Map<Long,BigDecimal> expected=new HashMap<>();if(order.groupOrderId!=null&&"INDIVIDUAL".equals(refs.one("select payment_mode from group_orders where id=?",order.groupOrderId).get("payment_mode"))){for(var row:refs.list("select user_id,amount_due from group_order_members where order_id=?",order.id))expected.put(((Number)row.get("user_id")).longValue(),new BigDecimal(row.get("amount_due").toString()));}else expected.put(order.userId,order.finalAmount);if(all.size()!=expected.size()||all.stream().anyMatch(row->!expected.containsKey(row.userId)||row.amount.compareTo(expected.get(row.userId))!=0)||all.stream().map(row->row.amount).reduce(BigDecimal.ZERO,BigDecimal::add).compareTo(order.finalAmount)!=0||requirePaid&&all.stream().anyMatch(row->!"SUCCESS".equals(row.status)))throw OrderProblem.conflict("Chưa đủ toàn bộ thành viên thanh toán chính xác phần tiền.");}
 public String qrSvg(String content){try{var matrix=new com.google.zxing.qrcode.QRCodeWriter().encode(content,com.google.zxing.BarcodeFormat.QR_CODE,0,0,Map.of(com.google.zxing.EncodeHintType.MARGIN,4));StringBuilder path=new StringBuilder();for(int y=0;y<matrix.getHeight();y++)for(int x=0;x<matrix.getWidth();x++)if(matrix.get(x,y))path.append("M").append(x).append(' ').append(y).append("h1v1h-1z");return "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 "+matrix.getWidth()+" "+matrix.getHeight()+"\" role=\"img\" aria-label=\"Mã QR thanh toán\"><rect width=\"100%\" height=\"100%\" fill=\"white\"/><path d=\""+path+"\" fill=\"black\"/></svg>";}catch(Exception error){throw new IllegalStateException("Không tạo được QR.",error);}}
}
